(2509656, 343806, 29011, '<td valign="top">Very nice landscape. The midtones are a tad too dark though, a little boost via Levels in Photoshop would''ve worked nicely :) -9</td>', 'Very nice landscape. The midtones are a tad too dark though, a little boost via Levels in Photoshop would''ve worked nicely :) -9', '2006-06-12 15:06:51.000000', NULL, 1),
(2509660, 343363, 29011, '<td valign="top">Great job! An easy favorite from the challenge. This one''s got to place high in the placings. 10</td>', 'Great job! An easy favorite from the challenge. This one''s got to place high in the placings. 10', '2006-06-12 15:08:01.000000', NULL, 1),
(2509674, 343696, 29011, '<td valign="top">Beautiful warm light. I really like the Summer/Spring take on the shot. As good maybe even better than the first take. <br/>Minor nitpick, perhaps dodging the eyes just a bit, to bring them out more since they are kinda dark.</td>', 'Beautiful warm light. I really like the Summer/Spring take on the shot. As good maybe even better than the first take. Minor nitpick, perhaps dodging the eyes just a bit, to bring them out more since they are kinda dark.', '2006-06-12 15:12:35.000000', NULL, 1),
(2509685, 343601, 29011, '<td valign="top">A really nice overall improvement. I like the composition more and the colors look better. Scored it down a point because of the destracting blown highlighs in the torso area of the nightgown.</td>', 'A really nice overall improvement. I like the composition more and the colors look better. Scored it down a point because of the destracting blown highlighs in the torso area of the nightgown.', '2006-06-12 15:16:29.000000', NULL, 1),
(2509689, 341272, 29011, '<td valign="top">Awesome detail. Great closeup :)</td>', 'Awesome detail. Great closeup :)', '2006-06-12 15:17:19.000000', NULL, 1),
(2509698, 343771, 12448, '<td valign="top">I liked the original better, more edgy and grungy looking.  This is too clean for my taste.  a 6</td>', 'I liked the original better, more edgy and grungy looking.  This is too clean for my taste.  a 6', '2006-06-12 15:21:01.000000', NULL, 1),
(2509699, 343638, 327, '<td valign="top">Very engaging shot. I really like this.</td>', 'Very engaging shot. I really like this.', '2006-06-12 15:21:04.000000', NULL, 1),
(2509705, 343696, 327, '<td valign="top">Wonderful shot. It looks like she''s walking right out of the photo. Really nicely done. Bravo!</td>', 'Wonderful shot. It looks like she''s walking right out of the photo. Really nicely done. Bravo!', '2006-06-12 15:25:19.000000', NULL, 1),
(2509714, 341272, 12448, '<td valign="top">reatke of I''m sorry?  If so, excellent!  Much better!  A 9</td>', 'reatke of I''m sorry?  If so, excellent!  Much better!  A 9', '2006-06-12 15:30:09.000000', NULL, 1),
(2509729, 343638, 52296, '<td valign="top">Lovely shot!</td>', 'Lovely shot!', '2006-06-12 15:34:57.000000', NULL, 1),
(2509732, 343806, 52296, '<td valign="top">Very nice colours, like it!</td>', 'Very nice colours, like it!', '2006-06-12 15:35:50.000000', NULL, 1),
(2509734, 343324, 12448, '<td valign="top">fordmanf1?  If so, excellent improvement.  I liked the original, I love this one!  Better lines, sharper image, nice colors.  A 9</td>', 'fordmanf1?  If so, excellent improvement.  I liked the original, I love this one!  Better lines, sharper image, nice colors.  A 9', '2006-06-12 15:36:24.000000', NULL, 1),
(2509735, 343601, 52296, '<td valign="top">Very nice indeed!</td>', 'Very nice indeed!', '2006-06-12 15:36:55.000000', NULL, 1),
(2509739, 343558, 12448, '<td valign="top">Djabordjabor I presume?  Very nice improvement over the original.  The DOF is very shallow, bringing me to the driver, nice.  The shot isn''t as cluttered and the colors are very nicely done.  And you removed that irritating passenger, LOL  The original got a 5 from me, the Take Two gets an 8 for improvement and originality :)</td>', 'Djabordjabor I presume?  Very nice improvement over the original.  The DOF is very shallow, bringing me to the driver, nice.  The shot isn''t as cluttered and the colors are very nicely done.  And you removed that irritating passenger, LOL  The original got a 5 from me, the Take Two gets an 8 for improvement and originality :)', '2006-06-12 15:38:46.000000', NULL, 1),
(2509740, 343540, 52296, '<td valign="top">Nice composition!</td>', 'Nice composition!', '2006-06-12 15:39:19.000000', NULL, 1),
(2509743, 343062, 52296, '<td valign="top">Excellent abstract!</td>', 'Excellent abstract!', '2006-06-12 15:40:20.000000', NULL, 1),
(2509753, 342918, 52296, '<td valign="top">Well captured,bright and sharp!</td>', 'Well captured,bright and sharp!', '2006-06-12 15:43:34.000000', NULL, 1),
(2509754, 341962, 12448, '<td valign="top">Qiki?  Retake of City Moorings?  This is an improvement without a doubt.  You can see more detail, the foreground isn''t so cluttered.  Very nice, but you still seem to having some focus or clarity issues.  I didn''t get a chance to vote on the original but if I had it would have gotten a 4 or 5, this one gets a 7 for improvement and effort :)</td>', 'Qiki?  Retake of City Moorings?  This is an improvement without a doubt.  You can see more detail, the foreground isn''t so cluttered.  Very nice, but you still seem to having some focus or clarity issues.  I didn''t get a chance to vote on the original but if I had it would have gotten a 4 or 5, this one gets a 7 for improvement and effort :)', '2006-06-12 15:43:40.000000', NULL, 1),
(2509758, 343233, 12448, '<td valign="top">I have no reference to the original on this one so I can''t look it up.  If you would like to send me the link so I can see the difference I would be happy to rethink my score.  As is, very noisy, focus is lacking and it looks to be a some camera shake involved.  As is a 4</td>', 'I have no reference to the original on this one so I can''t look it up.  If you would like to send me the link so I can see the difference I would be happy to rethink my score.  As is, very noisy, focus is lacking and it looks to be a some camera shake involved.  As is a 4', '2006-06-12 15:45:02.000000', NULL, 1),
(2509760, 343825, 52296, '<td valign="top">Nice idea, like the outcome!</td>', 'Nice idea, like the outcome!', '2006-06-12 15:45:36.000000', NULL, 1),
(2509766, 340739, 52296, '<td valign="top">Like the composition, great shot!</td>', 'Like the composition, great shot!', '2006-06-12 15:47:30.000000', NULL, 1),
(2509770, 342619, 12448, '<td valign="top">Having no reference to the original (Looked in Jump Challenge, didn''t see it, not sure where else to look) I have to go on this shot on it''s own merits.  If you want to PM me a link to the original I can compare them and adjust your score up accordingly if needed.  As is, lacks that POP that makes me look more than once, a bit dull and flat.  A 6</td>', 'Having no reference to the original (Looked in Jump Challenge, didn''t see it, not sure where else to look) I have to go on this shot on it''s own merits.  If you want to PM me a link to the original I can compare them and adjust your score up accordingly if needed.  As is, lacks that POP that makes me look more than once, a bit dull and flat.  A 6', '2006-06-12 15:49:13.000000', NULL, 1),
(2509773, 343696, 52296, '<td valign="top">Excellent!</td>', 'Excellent!', '2006-06-12 15:50:06.000000', NULL, 1),
(2509778, 342840, 12448, '<td valign="top">MWitt?  LOL!   I love it!  Very nice, says much more than th original did and very creative!  I had given the original an 8 because I loved it but this one made me laugh as well so you get a 10! :)</td>', 'MWitt?  LOL!   I love it!  Very nice, says much more than th original did and very creative!  I had given the original an 8 because I loved it but this one made me laugh as well so you get a 10! :)', '2006-06-12 15:51:21.000000', NULL, 1),
(2509922, 342914, 18197, '<td valign="top">I tend to like these ink in water photos and this one is pretty well done. There are a couple of things that would have made it better in my opinion. In the lower left corner there is a near verticle line that is distracting. Tighter crop would eliminate it. Across the top there is a black line that is also distracting. same solution. Again in the lower left corner, there is a blue smudge below the ink. Can''t tell if it was there on purpose or an artifact of post processing.</td>', 'I tend to like these ink in water photos and this one is pretty well done. There are a couple of things that would have made it better in my opinion. In the lower left corner there is a near verticle line that is distracting. Tighter crop would eliminate it. Across the top there is a black line that is also distracting. same solution. Again in the lower left corner, there is a blue smudge below the ink. Can''t tell if it was there on purpose or an artifact of post processing.', '2006-06-12 16:50:19.000000', NULL, 1),
(2509943, 343779, 18197, '<td valign="top">In a photo like this (IMO) the focus works best if it''s brilliantly sharp. The edge of the watch closest to the camera is just outside the DOF region of perfect focus. Better (again IMO) if the part you see most clearly were what was in perfect focus. Also, the handgun and backgrown are nearly equally dark and thus blend into one another. Better (IMO) to bring up the brightness of the background just a bit to provide clearer context.</td>', 'In a photo like this (IMO) the focus works best if it''s brilliantly sharp. The edge of the watch closest to the camera is just outside the DOF region of perfect focus. Better (again IMO) if the part you see most clearly were what was in perfect focus. Also, the handgun and backgrown are nearly equally dark and thus blend into one another. Better (IMO) to bring up the brightness of the background just a bit to provide clearer context.', '2006-06-12 16:54:55.000000', NULL, 1),
(2510017, 342891, 48204, '<td valign="top">When you stare at this picture it feels like it''s moving, like a pinwheel effect. Very nice   gave it a 9</td>', 'When you stare at this picture it feels like it''s moving, like a pinwheel effect. Very nice   gave it a 9', '2006-06-12 17:12:13.000000', NULL, 1),
(2510037, 342843, 35994, '<td valign="top">Beautiful colors, great water shot!!</td>', 'Beautiful colors, great water shot!!', '2006-06-12 17:18:09.000000', NULL, 1),
(2510042, 341251, 35994, '<td valign="top">AH, alcohol abuse!! lol, nice shot the background works good with the rest of the picture. :)</td>', 'AH, alcohol abuse!! lol, nice shot the background works good with the rest of the picture. :)', '2006-06-12 17:19:05.000000', NULL, 1),
(2510116, 343363, 19952, '<td valign="top">This is one of the best photos I''ve ever seen on this site. Absolutely gorgeous!</td>', 'This is one of the best photos I''ve ever seen on this site. Absolutely gorgeous!', '2006-06-12 17:58:52.000000', NULL, 1),
(2510131, 341215, 52925, '<td valign="top">Way too much saturation, but nice subject and composition.</td>', 'Way too much saturation, but nice subject and composition.', '2006-06-12 18:03:56.000000', NULL, 1),
(2510139, 343720, 52925, '<td valign="top">Sorry, the grain doesn''t work for me in this picture. Some NeatImage or USM could''ve helped.</td>', 'Sorry, the grain doesn''t work for me in this picture. Some NeatImage or USM could''ve helped.', '2006-06-12 18:09:19.000000', NULL, 1),
(2510151, 343233, 52925, '<td valign="top">This is a weird shot. First, there''s too much noise in the foreground. This could be done with some NeatImage. Then, the black glow around the figures look very unnatural, almost as if they are added to the background later. Lastly, the background itself is noisy and uninteresting.</td>', 'This is a weird shot. First, there''s too much noise in the foreground. This could be done with some NeatImage. Then, the black glow around the figures look very unnatural, almost as if they are added to the background later. Lastly, the background itself is noisy and uninteresting.', '2006-06-12 18:15:09.000000', NULL, 1),
(2510155, 343510, 52925, '<td valign="top">This shot would work better if you made the rings stand out some more. You can use masks in advanced editing, so yo could have boosted the saturation of only the rings. Apart from that still a nice shot.</td>', 'This shot would work better if you made the rings stand out some more. You can use masks in advanced editing, so yo could have boosted the saturation of only the rings. Apart from that still a nice shot.', '2006-06-12 18:18:07.000000', NULL, 1),
(2510166, 343740, 52925, '<td valign="top">Hahaha! Love this one! Really a brainteaser though. It might not appeal to everyone. Had to look a few times myself before I got it. Now that I do, I can''t take my eyes off it. Unreal expression and nice post processing.</td>', 'Hahaha! Love this one! Really a brainteaser though. It might not appeal to everyone. Had to look a few times myself before I got it. Now that I do, I can''t take my eyes off it. Unreal expression and nice post processing.', '2006-06-12 18:22:32.000000', NULL, 1),
(2510174, 342945, 52925, '<td valign="top">Not sure if the desat works for this. Higher contrast might improve the shot. Background sky is a bit boring.</td>', 'Not sure if the desat works for this. Higher contrast might improve the shot. Background sky is a bit boring.', '2006-06-12 18:25:24.000000', NULL, 1),
(2510239, 343601, 53147, '<td valign="top">Glad I remembered to come back to this one. I am bumping back up to the original score i had given you. I dropped it down to a 3 after my voting finished because of the long title splitting my screen. Took me a bit to figure out what was doing it. So bumping up 4 points right now back to a 7. Good shot with nice colors and DOF. Good job</td>', 'Glad I remembered to come back to this one. I am bumping back up to the original score i had given you. I dropped it down to a 3 after my voting finished because of the long title splitting my screen. Took me a bit to figure out what was doing it. So bumping up 4 points right now back to a 7. Good shot with nice colors and DOF. Good job', '2006-06-12 18:50:33.000000', NULL, 1),
(2510289, 343601, 48546, '<td valign="top">much better. Skin doesn''t appear to be as "plasticy". Pose and choice of crop is more flattering.</td>', 'much better. Skin doesn''t appear to be as "plasticy". Pose and choice of crop is more flattering.', '2006-06-12 19:09:04.000000', NULL, 1),
(2510294, 343363, 48546, '<td valign="top">You should get a ribbon for most improved shot Unnur.</td>', 'You should get a ribbon for most improved shot Unnur.', '2006-06-12 19:12:32.000000', NULL, 1),
(2510317, 343673, 12448, '<td valign="top">Much better color than the first, better crop, nicer image overall but I still don''t like the hand position very much, it''s the years of traveling with a portrait studio and watching them set up shots.  But still an improvement.  Your original got a 6 from me, this one gets a 9, would have been 10 if not for those hands! :)</td>', 'Much better color than the first, better crop, nicer image overall but I still don''t like the hand position very much, it''s the years of traveling with a portrait studio and watching them set up shots.  But still an improvement.  Your original got a 6 from me, this one gets a 9, would have been 10 if not for those hands! :)', '2006-06-12 19:26:21.000000', NULL, 1),
(2510321, 342718, 12448, '<td valign="top">OMGoodness!  What an improvement over the original!  Fantastic color, clouds, everything but the horizon and tower straightness.  It still seems a tad off, leaning to the right, just a touch.  I would have given the original a 4 or 5 if I had voted in that challenge, this one gets an 8 for color and clarity improvement! :)</td>', 'OMGoodness!  What an improvement over the original!  Fantastic color, clouds, everything but the horizon and tower straightness.  It still seems a tad off, leaning to the right, just a touch.  I would have given the original a 4 or 5 if I had voted in that challenge, this one gets an 8 for color and clarity improvement! :)', '2006-06-12 19:29:02.000000', NULL, 1),
(2510328, 343830, 12448, '<td valign="top">Shail!!!!  Nice!  Very nice!  HUGE improvement over the original.  Focused on one shell, not three, better color, nice pop to the shot.  Only two little things bother me, the shell looks a tad oversharpened and the orange background.  I would have stuck with black but that''s me.  I would have given the original a 5, but this one gets an 8 for overall improvement and effort! ;)</td>', 'Shail!!!!  Nice!  Very nice!  HUGE improvement over the original.  Focused on one shell, not three, better color, nice pop to the shot.  Only two little things bother me, the shell looks a tad oversharpened and the orange background.  I would have stuck with black but that''s me.  I would have given the original a 5, but this one gets an 8 for overall improvement and effort! ;)', '2006-06-12 19:33:20.000000', NULL, 1),
(2510335, 343740, 12448, '<td valign="top">Wow, talk about an improvement on a shot!  You''ve come a long way, kiddo!  LOL!  An 8 for overall improvement and humor! ;) :)</td>', 'Wow, talk about an improvement on a shot!  You''ve come a long way, kiddo!  LOL!  An 8 for overall improvement and humor! ;) :)', '2006-06-12 19:39:39.000000', NULL, 1),
(2510341, 343673, 48546, '<td valign="top">Color is better, lighting has more depth. Good job.</td>', 'Color is better, lighting has more depth. Good job.', '2006-06-12 19:43:36.000000', NULL, 1),
(2510346, 343354, 12448, '<td valign="top">Okay, it looks older now but, I know, those horrible buts, I''m turned off by the tilt of the shot.  I keep thinking the jeep is going to roll back down the hill, but that''s probably just me.  It is an improvement over the original as far as what you were trying to convey (making it look like an older shot) but still lacks a punch, maybe a slight contrast bump or levels adjustment?  Also, the lack of focus or soft focus also doesn''t work for me on this shot, but again, just my opinion.  If I had voted on the original it would have gotten a 5, this one gets a 7 for improving what you wanted to convey and a nice feel to the shot overall.</td>', 'Okay, it looks older now but, I know, those horrible buts, I''m turned off by the tilt of the shot.  I keep thinking the jeep is going to roll back down the hill, but that''s probably just me.  It is an improvement over the original as far as what you were trying to convey (making it look like an older shot) but still lacks a punch, maybe a slight contrast bump or levels adjustment?  Also, the lack of focus or soft focus also doesn''t work for me on this shot, but again, just my opinion.  If I had voted on the original it would have gotten a 5, this one gets a 7 for improving what you wanted to convey and a nice feel to the shot overall.', '2006-06-12 19:45:08.000000', NULL, 1),
(2510353, 341802, 12448, '<td valign="top">Okay, an improvement for sure.  Much better contrast and clarity on this shot than the original, spistole.  I like the idea of making it a mirror image but there are a few little things that bug me, mostly the line in the middle of the shot, the blue line and spots all over the bulb.  If you had cloned those out this would be very good.  Also the mirror looks like it was shaking while the shot was being done.  Your original shot got a 4 from me, this one gets a 7 for improvement and better quality!  Much better! :)</td>', 'Okay, an improvement for sure.  Much better contrast and clarity on this shot than the original, spistole.  I like the idea of making it a mirror image but there are a few little things that bug me, mostly the line in the middle of the shot, the blue line and spots all over the bulb.  If you had cloned those out this would be very good.  Also the mirror looks like it was shaking while the shot was being done.  Your original shot got a 4 from me, this one gets a 7 for improvement and better quality!  Much better! :)', '2006-06-12 19:49:01.000000', NULL, 1),
(2510372, 341215, 48546, '<td valign="top">Holy saturation Batman.<br/>Split the difference on the shutter speed and saturation boost between this and the last one, and I''ll give you a 10.<br/>As it is, 8</td>', 'Holy saturation Batman.Split the difference on the shutter speed and saturation boost between this and the last one, and I''ll give you a 10.As it is, 8', '2006-06-12 19:54:39.000000', NULL, 1),
(2510376, 342918, 12448, '<td valign="top">scarbrd, right?  Nice, very nice improvement.  Got rid of the distraction in the aisle and the composition is much better in this one.  I like the feel of the shot overall.  The only thing that bothers me betweent this one and the original is the original looked a bit brighter and whiter.  But otherwise, much better.  I would have given the original a 5, this one gets a 7 for improvement and just cuz it deserves it! ;)</td>', 'scarbrd, right?  Nice, very nice improvement.  Got rid of the distraction in the aisle and the composition is much better in this one.  I like the feel of the shot overall.  The only thing that bothers me betweent this one and the original is the original looked a bit brighter and whiter.  But otherwise, much better.  I would have given the original a 5, this one gets a 7 for improvement and just cuz it deserves it! ;)', '2006-06-12 19:55:54.000000', NULL, 1),
(2510384, 343638, 57886, '<td valign="top">Wow... great picture. Clear - bright- sharp - good colors, nice to add the leaves :o) excellent.</td>', 'Wow... great picture. Clear - bright- sharp - good colors, nice to add the leaves :o) excellent.', '2006-06-12 19:58:14.000000', NULL, 1),
(2510388, 343727, 57886, '<td valign="top">Nice capture.. shows so much life :o) Nice focus on the two horses in front.. perfect. 10</td>', 'Nice capture.. shows so much life :o) Nice focus on the two horses in front.. perfect. 10', '2006-06-12 19:59:32.000000', NULL, 1),
(2510393, 343173, 48546, '<td valign="top">Looks like you increased the delay some in your trigger. Got it right this time. Good job.</td>', 'Looks like you increased the delay some in your trigger. Got it right this time. Good job.', '2006-06-12 20:00:54.000000', NULL, 1),
(2510399, 343838, 12448, '<td valign="top">Okay, found the original and this is hard to say but I''m not seeing much improvement here.  The original is okay, lacks a certain POP factor and the color in this one helps that a bit but this one still remains a bit flat overall.  The first one was in focus but this one seems blurred and if you were going for a dreamy state or soft focus, it does not come across to me in that manner.  The lighting is very harsh on this one, on board flash?  The shadows from the ticket and her chest are noticable.  Not sure of the steps you took in post processing but if you want to talk about it after the challenge I would be happy to offer a few suggestions in making this a more IN YOUR FACE type shot.  It''s a very good improvement over the first in set up and composition.  The original, if I had voted would have gotten a 4 or 5 from me this one gets a 6 for effort and improvement.  :)</td>', 'Okay, found the original and this is hard to say but I''m not seeing much improvement here.  The original is okay, lacks a certain POP factor and the color in this one helps that a bit but this one still remains a bit flat overall.  The first one was in focus but this one seems blurred and if you were going for a dreamy state or soft focus, it does not come across to me in that manner.  The lighting is very harsh on this one, on board flash?  The shadows from the ticket and her chest are noticable.  Not sure of the steps you took in post processing but if you want to talk about it after the challenge I would be happy to offer a few suggestions in making this a more IN YOUR FACE type shot.  It''s a very good improvement over the first in set up and composition.  The original, if I had voted would have gotten a 4 or 5 from me this one gets a 6 for effort and improvement.  :)', '2006-06-12 20:02:07.000000', NULL, 1),
(2510410, 342990, 12448, '<td valign="top">dragonlady?  WOW!  What a pretty kitty!  Much better than the original blue and red one, LOL :)  An 8!</td>', 'dragonlady?  WOW!  What a pretty kitty!  Much better than the original blue and red one, LOL :)  An 8!', '2006-06-12 20:04:14.000000', NULL, 1),
(2510416, 343670, 12448, '<td valign="top">Baron152!  WOW!  Compared to the original all I can say is WOW!!!!!  A 10, fantastic improvement and well done overall! ;)</td>', 'Baron152!  WOW!  Compared to the original all I can say is WOW!!!!!  A 10, fantastic improvement and well done overall! ;)', '2006-06-12 20:06:40.000000', NULL, 1),
(2510424, 342889, 12448, '<td valign="top">mike clooney!  Talk about improvement!  Very well done, you listened, you reshot and it''s much better.  A 6</td>', 'mike clooney!  Talk about improvement!  Very well done, you listened, you reshot and it''s much better.  A 6', '2006-06-12 20:10:32.000000', NULL, 1),
(2510570, 341215, 42198, '<td valign="top">Too much saturation for my taste. You''ve created a great piece of surreal/fantasy art, but that green is just too much! :)</td>', 'Too much saturation for my taste. You''ve created a great piece of surreal/fantasy art, but that green is just too much! :)', '2006-06-12 21:14:06.000000', NULL, 1),
(2510578, 343354, 42198, '<td valign="top">You''ve put a lot of effort into making the *photo* look old, and that works well. But the jeep itself still looks shiny and new!</td>', 'You''ve put a lot of effort into making the *photo* look old, and that works well. But the jeep itself still looks shiny and new!', '2006-06-12 21:18:56.000000', NULL, 1),
(2510646, 343727, 35602, '<td valign="top">Really nice action shot.  I love the way the mud is being flung by the hooves.  This really makes you hear the race noise.</td>', 'Really nice action shot.  I love the way the mud is being flung by the hooves.  This really makes you hear the race noise.', '2006-06-12 21:50:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2510664, 342856, 35602, '<td valign="top">Well, Bear, I like the original shot better.  I think it was the way the boat took up more of the composition than in this one.  The colors are very vibrant and beautiful on this one, but it seems to have lost some of the magic the original had.  I did not feel your original was overprocessed, though many of the comments indicated that.  Still, both are nice shots but I really like the original much better.</td>', 'Well, Bear, I like the original shot better.  I think it was the way the boat took up more of the composition than in this one.  The colors are very vibrant and beautiful on this one, but it seems to have lost some of the magic the original had.  I did not feel your original was overprocessed, though many of the comments indicated that.  Still, both are nice shots but I really like the original much better.', '2006-06-12 22:00:01.000000', NULL, 1),
(2510673, 343540, 35602, '<td valign="top">I like the leading line on this one.  It brings your eye right to the minimal lighthouse, which works well with this composition.  Image could be sharper with more detail on the brick facade (is it brick?  Can''t tell.)</td>', 'I like the leading line on this one.  It brings your eye right to the minimal lighthouse, which works well with this composition.  Image could be sharper with more detail on the brick facade (is it brick?  Can''t tell.)', '2006-06-12 22:05:35.000000', NULL, 1),
