(2522444, 343696, 17126, '<td valign="top">she looks like amanda bines.</td>', 'she looks like amanda bines.', '2006-06-16 12:28:58.000000', NULL, 0),
(2522764, 343779, 53147, '<td valign="top">Trading Post -<br/> <br/>First off - Welcome back to the fold!!! We have missed you. Now on to business. I scored this a 5. I didnt look back at the original, but I think this would have been better had the whole watch face been sharp. The color on the watch looks good and on my monitor I can see the gun just fine. I guess it is just the concept that left me a bit flat - just didnt grab me.<br/> <br/>Quick comparison to original - I think your postprocess work was better on this one but theconcept was better on the original. Hope any of this helps.</td>', 'Trading Post - First off - Welcome back to the fold!!! We have missed you. Now on to business. I scored this a 5. I didnt look back at the original, but I think this would have been better had the whole watch face been sharp. The color on the watch looks good and on my monitor I can see the gun just fine. I guess it is just the concept that left me a bit flat - just didnt grab me. Quick comparison to original - I think your postprocess work was better on this one but theconcept was better on the original. Hope any of this helps.', '2006-06-16 15:19:40.000000', NULL, 0),
(2522795, 343217, 53147, '<td valign="top">Trading Post - <br/> <br/>I will start with the fact that I prefer this much better than your original. I like that there is alot of different stuff to see as you look over this shot - the branches up top, the reflection, the trees under the arches.  A much more pleasant picture overall. Maybe a tad soft as a whole but you can see a wonderful array of textures throughout. The bright white spot on the right i nthe gap on the bridge is a shame as it is a bit distracting. The pieces of tree in the others work well to soften those areas. I do like the postprocessingf on this. It gives it a funky feel but the light greens may be a bit too yellow from these actions (I dont have actions that I know of on Elements so I am jealous). Good shot and great improvement.</td>', 'Trading Post -  I will start with the fact that I prefer this much better than your original. I like that there is alot of different stuff to see as you look over this shot - the branches up top, the reflection, the trees under the arches.  A much more pleasant picture overall. Maybe a tad soft as a whole but you can see a wonderful array of textures throughout. The bright white spot on the right i nthe gap on the bridge is a shame as it is a bit distracting. The pieces of tree in the others work well to soften those areas. I do like the postprocessingf on this. It gives it a funky feel but the light greens may be a bit too yellow from these actions (I dont have actions that I know of on Elements so I am jealous). Good shot and great improvement.', '2006-06-16 15:34:36.000000', NULL, 0),
(2522841, 343740, 14773, '<td valign="top">Gotcha. Great shot.</td>', 'Gotcha. Great shot.', '2006-06-16 16:17:17.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
